/**
 * Stub de declaración para el paquete `server-only`.
 *
 * Permite que `import 'server-only'` pase la verificación de TypeScript
 * sin instalar el paquete. En producción Next.js aplica la restricción
 * a través del bundler (webpack/turbopack).
 *
 * Para instalar el paquete real: npm install server-only
 * Una vez instalado, este archivo puede eliminarse.
 */
declare module 'server-only' {}
